import re

VALID_METHODS = {'GET', 'POST', 'PUT', 'DELETE', 'PATCH'}
VALID_PERMS = {'ALLOW', 'DENY'}
VAR_RE = re.compile(r'\{[A-Za-z0-9_-]+\}')


def norm(path):
    return VAR_RE.sub('{var}', path)


def segs(path):
    return [s for s in path.split('/') if s]


def is_strict_prefix(a, b):
    sa, sb = segs(a), segs(b)
    return len(sa) < len(sb) and sb[:len(sa)] == sa


def main():
    with open('/app/input.txt') as fh:
        lines = [l.rstrip('\r\n') for l in fh.readlines()]

    i = 0
    while i < len(lines) and not lines[i].strip():
        i += 1
    ep_lines = []
    while i < len(lines) and lines[i].strip():
        ep_lines.append(lines[i])
        i += 1
    rest = lines[i:]

    meta_lines, plan_lines = [], []
    for l in rest:
        s = l.split()
        if not s:
            continue
        if s[0].lower() in ('base', 'exclude'):
            meta_lines.append(s)
        else:
            plan_lines.append(s)

    eps = []
    name_map = {}
    for l in ep_lines:
        f = l.split()
        if len(f) != 4:
            break
        path, method, role, perm = f
        m = method.upper()
        p = perm.upper()
        if (not path.strip() or m not in VALID_METHODS or
                p not in VALID_PERMS or not role.strip()):
            break
        eps.append((path, m, role, p))
        name_map.setdefault(norm(path), path)

    base = None
    exclude = set()
    for f in meta_lines:
        if f[0].lower() == 'base':
            base = f[1] if len(f) > 1 else None
        elif f[0].lower() == 'exclude':
            exclude.update(f[1:])

    plan = []
    for f in plan_lines:
        if len(f) != 2:
            break
        path, method = f
        m = method.upper()
        if m not in VALID_METHODS or not path.strip():
            break
        plan.append((norm(path), m))

    eligible = [e for e in eps if base is None or e[0].startswith(base)]

    if not plan:
        selected = [e for e in eligible if e[2] not in exclude]
    else:
        plan_set = set(plan)
        plan_norms = set(pn for pn, _ in plan)
        chosen = set()
        by_norm = {}
        for idx, e in enumerate(eligible):
            by_norm.setdefault(norm(e[0]), []).append(idx)
            if (norm(e[0]), e[1]) in plan_set and e[2] not in exclude:
                chosen.add(idx)
        for pn2, idxs in by_norm.items():
            if any(is_strict_prefix(pn2, pn) for pn in plan_norms):
                nonex = [j for j in idxs if eligible[j][2] not in exclude]
                chosen.update(nonex if nonex else idxs)
        selected = [eligible[j] for j in sorted(chosen)]

    seen = set()
    result = []
    for path, m, role, perm in selected:
        key = (norm(path), m, role)
        if key in seen:
            continue
        seen.add(key)
        result.append((name_map[norm(path)], m, role, perm))

    result.sort(key=lambda r: (-len(segs(r[0])), r[1], r[2], r[3]))

    if not result:
        out = '\n'
    else:
        out = ''.join('%s %s %s %s\n' % r for r in result)

    with open('/app/output.txt', 'w') as fh:
        fh.write(out)


if __name__ == '__main__':
    main()
